// Process evolution eligibility for each pet
const pets = $input.first().json.data || [];
const evolutionCandidates = [];

for (const pet of pets) {
  const evolutionReadiness = checkEvolutionReadiness(pet);

  if (evolutionReadiness.ready) {
    evolutionCandidates.push({
      petId: pet.id,
      petName: pet.name,
      currentType: pet.typeId,
      currentStage: pet.evolutionStage,
      nextStage: evolutionReadiness.nextStage,
      requirements: evolutionReadiness.requirements,
      progress: evolutionReadiness.currentProgress,
      priority: calculateEvolutionPriority(pet, evolutionReadiness)
    });
  }
}

// Sort by priority
evolutionCandidates.sort((a, b) => b.priority - a.priority);

return { 
  eligiblePets: evolutionCandidates, 
  totalChecked: pets.length,
  candidatesFound: evolutionCandidates.length 
};

function checkEvolutionReadiness(pet) {
  // Simulate evolution readiness check
  const baseRequirements = {
    level: pet.level >= (pet.evolutionStage + 1) * 20,
    bonding: pet.bonding >= (pet.evolutionStage + 1) * 25,
    experience: pet.experience >= calculateRequiredExperience(pet.evolutionStage)
  };

  const allMet = Object.values(baseRequirements).every(req => req);
  const progress = calculateEvolutionProgress(baseRequirements);

  return {
    ready: allMet && progress >= 1.0,
    nextStage: pet.evolutionStage + 1,
    requirements: baseRequirements,
    currentProgress: progress
  };
}

function calculateRequiredExperience(currentStage) {
  return Math.floor(500 * Math.pow(1.5, currentStage));
}

function calculateEvolutionProgress(requirements) {
  const reqValues = Object.values(requirements);
  const metCount = reqValues.filter(Boolean).length;
  return metCount / reqValues.length;
}

function calculateEvolutionPriority(pet, readiness) {
  let priority = 0;

  // Higher priority for pets with higher bonding
  priority += pet.bonding / 20;

  // Higher priority for pets that have been waiting longer
  const timeSinceLastEvolution = Date.now() - (pet.lastEvolution || 0);
  const daysSinceEvolution = timeSinceLastEvolution / (1000 * 60 * 60 * 24);
  priority += Math.min(daysSinceEvolution / 7, 3); // Max 3 points for waiting

  // Higher priority for pets closer to max level
  priority += pet.level / 50;

  // Higher priority for legendary pets (rare)
  if (pet.rarity === 'legendary') priority += 5;
  else if (pet.rarity === 'epic') priority += 3;
  else if (pet.rarity === 'rare') priority += 1;

  return Math.floor(priority * 10) / 10; // Round to 1 decimal place
}

