// Process evolution for eligible pets
const eligiblePets = $input.first().json.eligiblePets || [];
const evolutionResults = [];

// Process up to 3 evolutions per run to prevent overload
const maxEvolutions = Math.min(eligiblePets.length, 3);
const petsToEvolve = eligiblePets.slice(0, maxEvolutions);

for (const candidate of petsToEvolve) {
  try {
    console.log(`Starting evolution for pet: ${candidate.petName}`);

    // Get detailed pet information
    const petResponse = await $helpers.httpRequest({
      method: 'GET',
      url: `http://localhost:3000/api/pets/${candidate.petId}`,
      headers: { 'Content-Type': 'application/json' }
    });

    const pet = petResponse.data;

    // Check for special evolution conditions
    const specialEvolutions = await checkSpecialEvolutions(pet);
    let evolutionResult;

    if (specialEvolutions.length > 0) {
      // Attempt special evolution first
      evolutionResult = await attemptSpecialEvolution(pet, specialEvolutions[0]);
    } else {
      // Standard evolution
      evolutionResult = await attemptStandardEvolution(pet);
    }

    evolutionResults.push({
      petId: candidate.petId,
      petName: candidate.petName,
      previousStage: candidate.currentStage,
      evolutionType: evolutionResult.type,
      success: evolutionResult.success,
      result: evolutionResult,
      timestamp: new Date().toISOString()
    });

    // Add delay between evolutions
    await new Promise(resolve => setTimeout(resolve, 2000));

  } catch (error) {
    console.error(`Evolution failed for pet ${candidate.petName}:`, error);
    evolutionResults.push({
      petId: candidate.petId,
      petName: candidate.petName,
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }
}

return {
  processedPets: petsToEvolve.length,
  totalEligible: eligiblePets.length,
  skippedPets: eligiblePets.length - petsToEvolve.length,
  results: evolutionResults
};

async function checkSpecialEvolutions(pet) {
  try {
    const response = await $helpers.httpRequest({
      method: 'GET',
      url: `http://localhost:3000/api/pets/${pet.id}/special-evolutions`,
      headers: { 'Content-Type': 'application/json' }
    });
    return response.data.possibleEvolutions || [];
  } catch (error) {
    console.log('No special evolutions available:', error.message);
    return [];
  }
}

async function attemptSpecialEvolution(pet, specialEvolution) {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: `http://localhost:3000/api/pets/${pet.id}/special-evolution`,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      evolutionId: specialEvolution.id,
      forced: false
    })
  });

  return {
    type: 'special',
    evolutionName: specialEvolution.name,
    ...response.data
  };
}

async function attemptStandardEvolution(pet) {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: `http://localhost:3000/api/pets/${pet.id}/evolution`,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      forced: false
    })
  });

  return {
    type: 'standard',
    ...response.data
  };
}

// Prepare comprehensive evolution summary
const data = $input.first().json;
const results = data.results || [];

const summary = {
  processingDate: new Date().toISOString(),
  statistics: {
    totalProcessed: data.processedPets || 0,
    successfulEvolutions: results.filter(r => r.success).length,
    failedEvolutions: results.filter(r => !r.success).length,
    totalEligible: data.totalEligible || 0,
    skippedPets: data.skippedPets || 0
  },
  evolutionDetails: results.map(result => ({
    petId: result.petId,
    petName: result.petName,
    evolutionType: result.evolutionType || 'unknown',
    success: result.success,
    previousStage: result.previousStage,
    newStage: result.result?.newStage,
    changes: result.result?.changes || {},
    error: result.error || null,
    timestamp: result.timestamp
  })),
  notifications: generateNotifications(results)
};

return summary;

function generateNotifications(results) {
  const notifications = [];

  // Successful evolutions
  const successful = results.filter(r => r.success);
  if (successful.length > 0) {
    notifications.push({
      type: 'evolution_success',
      title: `🎉 Pet Evolution Complete!`,
      message: `${successful.length} pet(s) have successfully evolved!`,
      pets: successful.map(r => ({ name: r.petName, type: r.evolutionType })),
      priority: 'high'
    });
  }

  // Failed evolutions
  const failed = results.filter(r => !r.success);
  if (failed.length > 0) {
    notifications.push({
      type: 'evolution_failure',
      title: '⚠️ Evolution Failed',
      message: `${failed.length} pet(s) evolution attempts failed`,
      pets: failed.map(r => ({ name: r.petName, error: r.error })),
      priority: 'medium'
    });
  }

  // Special evolutions
  const specialEvolutions = successful.filter(r => r.evolutionType === 'special');
  if (specialEvolutions.length > 0) {
    notifications.push({
      type: 'special_evolution',
      title: '✨ Special Evolution Achieved!',
      message: `${specialEvolutions.length} rare special evolution(s) occurred!`,
      pets: specialEvolutions.map(r => ({ name: r.petName, result: r.result })),
      priority: 'legendary'
    });
  }

  return notifications;
}

// Handle pets that were skipped due to processing limits
const data = $input.first().json;
const skippedCount = data.totalEligible - data.processedPets;

if (skippedCount > 0) {
  return {
    message: 'Evolution processing completed with pending pets',
    timestamp: new Date().toISOString(),
    processed: data.processedPets,
    skipped: skippedCount,
    nextRun: new Date(Date.now() + 30 * 60 * 1000).toISOString(), // 30 minutes from now
    status: 'pending_remaining'
  };
} else {
  return {
    message: 'No pets eligible for evolution',
    timestamp: new Date().toISOString(),
    checked: data.totalChecked || 0,
    status: 'no_eligible_pets'
  };
}
